 "content": "def transform(grid):
    """Repeat each colored seed tile across its surrounding zero rectangle."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            # Each canvas is a 4-connected component of zero + seed cells.
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            colored = [(rr,cc) for rr,cc in comp if grid[rr][cc] not in (0,8)]
            if not colored:
                continue
            r0, r1 = min(x[0] for x in colored), max(x[0] for x in colored)
            c0, c1 = min(x[1] for x in colored), max(x[1] for x in colored)
            ph, pw = r1-r0+1, c1-c0+1
            pattern = [[0]*pw for _ in range(ph)]
            for rr,cc in colored:
                pattern[rr-r0][cc-c0] = grid[rr][cc]
            top, bottom = min(x[0] for x in comp), max(x[0] for x in comp)
            left, right = min(x[1] for x in comp), max(x[1] for x in comp)
            # The seed is positioned on a tile boundary; extend its pattern periodically.
            for rr in range(top, bottom+1):
                for cc in range(left, right+1):
                    out[rr][cc] = pattern[(rr-r0) % ph][(cc-c0) % pw]
    return out
